#!/usr/bin/env bash
# Run by a human in Azure Cloud Shell after the first successful GitHub deploy.
# Puts the two human-owned secrets into Key Vault without printing them, and points the staff
# login app at the real dashboard URL.
#   - entra-client-secret: generated by Entra and piped straight into Key Vault
#   - anthropic-api-key: you type it (hidden); it goes straight into Key Vault
set -euo pipefail

APP_RG="rg-ratedemo"
STAFF_APP=$(az ad app list --display-name "RateDemo staff login" --query "[0].appId" -o tsv)
KV=$(az keyvault list -g "$APP_RG" --query "[0].name" -o tsv)
API_FQDN=$(az containerapp show -g "$APP_RG" -n ca-api --query properties.configuration.ingress.fqdn -o tsv)
ME=$(az ad signed-in-user show --query id -o tsv)

echo "== Redirect URI for staff login: https://$API_FQDN/signin-oidc"
az ad app update --id "$STAFF_APP" --web-redirect-uris "https://$API_FQDN/signin-oidc"

echo "== Giving you permission to write secrets in $KV"
az role assignment create --assignee-object-id "$ME" --assignee-principal-type User \
  --role "Key Vault Secrets Officer" --scope "$(az keyvault show -n "$KV" --query id -o tsv)" -o none
echo "   waiting 60 s for the role to take effect..."; sleep 60

echo "== Entra client secret -> Key Vault (never shown)"
SECRET=$(az ad app credential reset --id "$STAFF_APP" --display-name ratedemo --years 1 --append --query password -o tsv)
az keyvault secret set --vault-name "$KV" -n entra-client-secret --value "$SECRET" -o none
unset SECRET

read -rsp "Paste your Anthropic API key (hidden), then Enter: " ANTHROPIC_KEY; echo
az keyvault secret set --vault-name "$KV" -n anthropic-api-key --value "$ANTHROPIC_KEY" -o none
unset ANTHROPIC_KEY

echo
echo "Done. Open https://$API_FQDN and sign in (wait ~5 minutes for the apps' secret cache to refresh)."
